import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:vaultvoice/core/db/database.dart';

import 'generated/schema.dart';

/// Generated by `drift_dev make-migrations` (FND-04 workflow), trimmed to the
/// checks that apply: every from→to pair migrates to a valid schema, and the
/// v1 → v2 step (APP-02 search index) backfills existing rows.
void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() => verifier = SchemaVerifier(GeneratedHelper()));

  group('simple database migrations', () {
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = VaultVoiceDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('[APP-02] v1 → v2 backfills the search index from existing '
      'recordings, transcripts and extractions', () async {
    final schema = await verifier.schemaAt(1);
    schema.rawDatabase
      ..execute(
        'INSERT INTO recordings (id, title, created_at, status, source, tags) '
        "VALUES ('r1', 'Standup', 0, 'recorded', 'mic', '[\"weekly\"]'), "
        "('r2', 'Memo', 0, 'recorded', 'mic', '[]')",
      )
      ..execute(
        'INSERT INTO transcripts (id, recording_id, model_id, language, '
        "created_at) VALUES ('t1', 'r1', 'm', 'en', 0)",
      )
      ..execute(
        'INSERT INTO transcript_segments (transcript_id, seq, start_ms, '
        "end_ms, body) VALUES ('t1', 0, 0, 1000, 'budget review'), "
        "('t1', 1, 1000, 2000, 'ship friday')",
      )
      ..execute(
        'INSERT INTO extractions (id, recording_id, profile_id, '
        "profile_version, model_id, json, valid, created_at) VALUES ('e1', "
        "'r2', 'meeting', 1, 'm', "
        '\'{"action_items":[{"task":"call plumber","owner":"Sam"}]}\', '
        '1, 0)',
      );
    final db = VaultVoiceDatabase(schema.newConnection());
    addTearDown(db.close);
    await verifier.migrateAndValidate(db, 2);

    Future<Set<String>> hits(String q) async => {
      for (final r
          in await db
              .customSelect(
                'SELECT recording_id FROM search_index WHERE search_index '
                'MATCH ?',
                variables: [Variable(q)],
              )
              .get())
        r.read<String>('recording_id'),
    };
    expect(await hits('weekly'), {'r1'});
    expect(await hits('friday'), {'r1'});
    expect(await hits('plumber'), {'r2'});
    expect(await hits('sam'), {'r2'});
  });

  test('[MAP-01/AC6] v2 → v3 adds mind_maps and keeps existing data, and '
      'maps cascade with the recording', () async {
    final schema = await verifier.schemaAt(2);
    schema.rawDatabase.execute(
      'INSERT INTO recordings (id, title, created_at, status, source, tags) '
      "VALUES ('r1', 'Standup', 0, 'recorded', 'mic', '[]')",
    );
    final db = VaultVoiceDatabase(schema.newConnection());
    addTearDown(db.close);
    await verifier.migrateAndValidate(db, 3);

    final recordings = await db.select(db.recordings).get();
    expect(recordings.single.title, 'Standup');
    expect(await db.select(db.mindMaps).get(), isEmpty);

    await db
        .into(db.mindMaps)
        .insert(
          MindMapsCompanion.insert(
            id: 'r1.mindmap',
            recordingId: 'r1',
            method: 'projection',
            json: {'id': 'n0', 'label': 'Root', 'children': <Object?>[]},
            nodeCount: 1,
            createdAt: DateTime.utc(2026),
          ),
        );
    await (db.delete(db.recordings)..where((r) => r.id.equals('r1'))).go();
    expect(await db.select(db.mindMaps).get(), isEmpty);
  });

  test('[ASK-03] v3 → v4 keeps recordings and the new Ask tables remove a '
      'turn when a cited recording is deleted', () async {
    final schema = await verifier.schemaAt(3);
    schema.rawDatabase.execute(
      'INSERT INTO recordings (id, title, created_at, status, source, tags) '
      "VALUES ('r1', 'Standup', 0, 'ready', 'recorded', '[]')",
    );
    final db = VaultVoiceDatabase(schema.newConnection());
    addTearDown(db.close);
    await verifier.migrateAndValidate(db, 4);
    await db.customStatement('PRAGMA foreign_keys = ON');

    expect(
      await db.customSelect('SELECT id FROM recordings').get(),
      hasLength(1),
    );
    await db.customStatement(
      'INSERT INTO ask_threads (id, created_at, updated_at) '
      "VALUES ('th', 0, 0)",
    );
    await db.customStatement(
      'INSERT INTO ask_turns (id, thread_id, seq, question, answer, found, '
      "created_at) VALUES ('tu', 'th', 0, 'q', 'a', 1, 0)",
    );
    await db.customStatement(
      "INSERT INTO ask_citations (turn_id, recording_id, t_ms) VALUES ('tu', "
      "'r1', 5)",
    );
    await db.customStatement("DELETE FROM recordings WHERE id = 'r1'");
    for (final t in ['ask_citations', 'ask_turns', 'ask_threads']) {
      expect(await db.customSelect('SELECT 1 FROM $t').get(), isEmpty);
    }
  });

  test('[TSK-02] v4 → v5 keeps recordings; reminder_exports rows go with '
      'their recording', () async {
    final schema = await verifier.schemaAt(4);
    schema.rawDatabase.execute(
      'INSERT INTO recordings (id, title, created_at, status, source, tags) '
      "VALUES ('r1', 'Standup', 0, 'ready', 'recorded', '[]')",
    );
    final db = VaultVoiceDatabase(schema.newConnection());
    addTearDown(db.close);
    await verifier.migrateAndValidate(db, 5);
    await db.customStatement('PRAGMA foreign_keys = ON');

    expect(
      await db.customSelect('SELECT id FROM recordings').get(),
      hasLength(1),
    );
    await db.customStatement(
      'INSERT INTO reminder_exports (item_key, recording_id, '
      'calendar_item_id, reminder_calendar_id, exported_at) '
      "VALUES ('k', 'r1', 'c', 'l', 0)",
    );
    await db.customStatement("DELETE FROM recordings WHERE id = 'r1'");
    expect(
      await db.customSelect('SELECT 1 FROM reminder_exports').get(),
      isEmpty,
    );
  });
}
